import {cdView} from './charts/cd.js';
import {ncdView} from './charts/ncd.js';
import {unitsView,parseUnitHash} from './units/units.js';
import {personnelView,mountPersonnel,unitPersonnel} from './personnel/personnel.js';
import {closeSidebar} from './sidebar.js';
import {publicationKey,publicationSetting,dataStatus,shouldPublish} from './utils/kpi-publication.js';
import {release,credit} from './config/release.js';
import {runtime} from './config/runtime.js';
import {request} from './api/request.js';
import {loadProfile,rest,readAll,login,logout,currentSession,refreshSession} from './api/supabase/client.js';
import {fetchGroup,fetchHdc} from './api/hdc/client.js';
import {number,sum,fiscalYear,fiscalMonths,monthNames,eligible,percent,kpiStatus,rank,facilityResults,organization,periodMatches,ncdSummary,formatSourceDate,escapeHtml as e} from './utils/core.js';
import {bars,columnChart} from './charts/charts.js';
const $=id=>document.getElementById(id);
const fmt=(v,d=0)=>v===null||v===undefined?'—':Number(v).toLocaleString('th-TH',{minimumFractionDigits:d,maximumFractionDigits:d});
$('developer-credit').textContent=credit;
const routes=[['overview','◫','ภาพรวมองค์กร'],['units','▤','หน่วยบริการ'],['area','◎','ผลงานพื้นที่ 7 หน่วย'],['service','✚','ผลงานบริการ 8 หน่วย'],['personnel','♧','บุคลากร'],['heatmap','▦','KPI Heatmap'],['trend','↗','แนวโน้ม'],['compare','⇄','เปรียบเทียบหน่วยบริการ'],['profile','▤','ข้อมูลหน่วยบริการ'],['finance','฿','งบประมาณและการเงิน'],['ncd','♡','โรคเรื้อรัง (NCD)'],['cd','◉','โรคติดต่อ'],['quality','✓','คุณภาพข้อมูล'],['manage','⚙','จัดการข้อมูล'],['kpi-admin','☑','จัดการ KPI (ADMIN)']];
const state={year:2569,period:'all',scope:'all',facility:'all',category:'all',route:'overview',kpi:null,facilities:[],kpis:[],inventory:[],profile:{tables:{},errors:[]},hdc:{},previous:{},permissions:[],selected:new Set(),rateMode:false,manageTable:'hp_finance_monthly',search:'',loading:true,generation:0};
const tableLabels={hp_finance_monthly:'เบิกจ่ายรายเดือน',hp_budget_monthly:'แผนงบประมาณ',hp_ncd_monthly:'ข้อมูล NCD',hp_cd_monthly:'โรคติดต่อ',hp_service_stats:'สถิติบริการอื่น',hp_staff:'บุคลากรแยกวิชาชีพ',hp_settings:'ตัวเลือกและการตั้งค่า',hp_data_quality:'รายการตรวจสอบคุณภาพ'};
function data(table){return state.profile.tables[table]??[];}
function facilities(){return state.facilities.filter(f=>f.active&&(state.scope!=='AREA'||f.area_unit)&&(state.facility==='all'||f.facility_code===state.facility));}
function published(k){if(state.profile.errors.some(r=>r.table==='hp_settings'))return false;return shouldPublish(publicationSetting(data('hp_settings'),k.kpi_id,state.year),dataStatus(state.hdc[k.kpi_id],recordSet(k)));}
function kpis(){return state.kpis.filter(k=>(state.scope==='all'||k.scope===state.scope)&&(state.category==='all'||k.category===state.category)&&published(k));}
function recordSet(k,previous=false){return facilityResults((previous?state.previous:state.hdc)[k.kpi_id]?.rows??[],k,state.facilities,state.period).filter(r=>state.facility==='all'||r.facility.facility_code===state.facility);}
function aggregate(k,previous=false){return organization(recordSet(k,previous),k);}
function valueLabel(v,k){return fmt(v,k.unit==='%'?1:0)+(v!==null&&v!==undefined?` ${k.unit}`:'');}
function badge(status){return `<span class="badge ${e(status.key)}">${e(status.text)}</span>`;}
function profileRows(table){return data(table).filter(r=>(state.facility==='all'||r.facility_code===state.facility)&&periodMatches(r,state.year,state.period));}
function stat(label,value,note='',feature=false){return `<div class="stat ${feature?'feature':''}"><div class="stat-label">${e(label)}</div><div class="stat-value ${String(value).length>11?'value-small':''}">${e(value)}</div><small>${e(note)}</small></div>`;}
function panel(title,content,description='',action=''){return `<section class="panel"><div class="panel-heading"><div><h2>${e(title)}</h2>${description?`<p class="subtle">${e(description)}</p>`:''}</div>${action}</div>${content}</section>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(c=>`<tr>${c.map(v=>`<td>${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">ไม่พบข้อมูลในช่วงเวลาที่เลือก</td></tr>`}</tbody></table></div>`;}
function canEdit(code){return !!currentSession()&&state.permissions.some(p=>p.role==='ADMIN'||p.facility_code===code);}
function admin(){return !!currentSession()&&state.permissions.some(p=>p.role==='ADMIN');}
function currentKpi(){const available=kpis();return available.find(k=>k.kpi_id===state.kpi)??available[0]??state.kpis[0];}
function kpiSelect(){const k=currentKpi();return `<label>ตัวชี้วัด<select id="kpi-selector">${kpis().map(v=>`<option value="${e(v.kpi_id)}" ${k?.kpi_id===v.kpi_id?'selected':''}>${e(v.name)}</option>`).join('')}</select></label><button data-live-hdc="${e(k.kpi_id)}" ${state.loading?'disabled':''}>ดึง API สด KPI นี้</button>`;}
function kpiCards(list=kpis()){if(!list.length)return '<div class="empty">ยังไม่มี KPI ที่พร้อมแสดงสำหรับปีและช่วงเวลาที่เลือก</div>';return `<div class="grid kpi-grid">${list.map(k=>{const a=aggregate(k),status=kpiStatus(a.value,k);return `<button class="panel kpi-card" data-kpi="${k.kpi_id}"><h3>${e(k.name)}</h3><div class="kpi-value">${e(valueLabel(a.value,k))}</div>${badge(status)}<div class="kpi-meta">${k.scope==='AREA'?'พื้นที่ 7 หน่วย':'บริการ 8 หน่วย'} • มีข้อมูล ${a.complete}/${a.expected}<br>เป้าหมาย ${k.target===null?'— ไม่ระบุ':fmt(k.target,1)+'%'}${a.partial?' • ข้อมูลไม่ครบ':''}</div></button>`;}).join('')}</div>`;}
function summaryTotals(){const allowed=facilities();const codes=new Set(allowed.filter(f=>f.area_unit).map(f=>f.facility_code));const population=profileRows('hp_population').filter(r=>codes.has(r.facility_code));const staff=profileRows('hp_staff');const vhv=profileRows('hp_volunteers');const budget=profileRows('hp_budget_monthly').filter(r=>r.review_status==='accepted');const finance=profileRows('hp_finance_monthly').filter(r=>r.review_status==='accepted');return {population:sum(population.map(r=>r.population)),households:sum(population.map(r=>r.households)),communities:sum(population.map(r=>r.communities)),staff:sum(staff.map(r=>r.staff_count)),support:sum(staff.map(r=>r.support_count)),volunteers:sum(vhv.map(r=>r.volunteer_count)),budget:sum(budget.map(r=>r.amount)),finance:sum(finance.map(r=>r.amount))};}
function overview(){
 const totals=summaryTotals();const values=kpis().map(k=>({k,a:aggregate(k)}));const evaluable=values.filter(({k,a})=>k.target!==null&&a.value!==null&&!a.partial&&k.direction!=='INFORMATION');const passed=evaluable.filter(({k,a})=>kpiStatus(a.value,k).key==='pass').length;const opd=state.kpis.find(k=>k.table==='s_opd_all');const opdValue=aggregate(opd);
 const cards=stat('หน่วยบริการทั้งหมด','8','รวมผลงานบริการครบ 8 แห่ง')+stat('หน่วยพื้นที่รับผิดชอบ','7','ประชากรพื้นที่ • ไม่รวมรหัส 45030')+stat('KPI ผ่านเกณฑ์',`${passed} / ${evaluable.length}`,'นับเฉพาะข้อมูลครบและมีเกณฑ์ยืนยัน',true)+stat('KPI ต้องเร่ง',fmt(evaluable.length-passed),'รวมใกล้เป้าและต่ำกว่าเป้า')+(published(opd)?stat('OPD รวม',fmt(opdValue.value),`มีข้อมูล ${opdValue.complete}/${opdValue.expected} หน่วย`):'')+stat('ประชากรพื้นที่',fmt(totals.population),'ข้อมูลพื้นฐานปีงบประมาณที่เลือก');
 const metrics=stat('หลังคาเรือน',fmt(totals.households))+stat('ชุมชน',fmt(totals.communities))+stat('บุคลากร',fmt(totals.staff),'เจ้าหน้าที่ ไม่รวมบุคลากรสนับสนุน')+stat('อสม.',fmt(totals.volunteers));
 const chart=bars(facilities().filter(f=>f.area_unit).map(f=>({label:f.short_name,value:data('hp_population').find(r=>r.facility_code===f.facility_code&&+r.fiscal_year===state.year)?.population??null})));
 const finance=stat('แผนเงินที่ยืนยันแล้ว',fmt(totals.budget,2),'บาท • รายการซ้ำรอตรวจสอบ')+stat('เบิกจ่ายสะสม',fmt(totals.finance,2),'บาท • ตามช่วงเวลาที่เลือก');
 const top=values.filter(({k,a})=>k.unit==='%'&&k.target!==null&&a.value!==null&&!a.partial).map(({k,a})=>({k,a,gap:k.direction==='LOWER_BETTER'?k.target-a.value:a.value-k.target})).sort((a,b)=>b.gap-a.gap);
 const gapTable=items=>table(['ตัวชี้วัด','ผลงาน','ผลต่างจากเป้า'],items.map(({k,a,gap})=>[`<button class="table-link" data-kpi="${k.kpi_id}">${e(k.name)}</button>`,e(valueLabel(a.value,k)),`${gap>=0?'+':''}${fmt(gap,1)} จุดร้อยละ`]));
 return `<div class="grid stats">${cards}</div><div class="grid stats">${metrics}</div><div class="grid two-columns">${panel('ประชากรในพื้นที่รับผิดชอบ',chart,'รวมเฉพาะ 7 หน่วยพื้นที่')}${panel('งบประมาณและการเบิกจ่าย',`<div class="grid half-columns">${finance}</div><p class="subtle">ข้อมูลจริงจาก Hospital Profile • แผนเงินอนุมานปีจากชุดข้อมูล FY2569</p><a href="#finance">ดูการเงินรายเดือน →</a>`)}</div><div class="grid half-columns">${panel('Top 5 KPI เทียบเป้าหมาย',gapTable(top.slice(0,5)))}${panel('5 KPI ที่ควรติดตาม',gapTable([...top].reverse().slice(0,5)))}</div><div class="row-title"><h2>ผลงานสุขภาพที่ติดตาม</h2><span class="scope-note">${values.length} ตัวชี้วัด • คลิกเพื่อดูรายละเอียด</span></div>${kpiCards()}`;
}
function performance(){const k=currentKpi();const rows=recordSet(k);const ranking=rank(rows,k);const a=aggregate(k);return panel('เลือกตัวชี้วัด',`<div class="controls">${kpiSelect()}</div>`)+`<div class="grid stats">${stat('ผลงานรวม',valueLabel(a.value,k),a.partial?'ข้อมูลไม่ครบทุกหน่วย':'รวมตัวตั้ง ÷ รวมตัวหาร',true)}${stat('ตัวตั้ง',fmt(a.numerator))}${stat('ตัวหาร',fmt(a.denominator))}${stat('เป้าหมาย',k.target===null?'—':fmt(k.target,1)+'%','ข้อมูลไม่มีเกณฑ์จะไม่ประเมินผ่าน/ไม่ผ่าน')}</div>`+panel(k.name,`<div class="grid half-columns"><div>${bars(ranking.map(r=>({label:r.facility.short_name,value:r.value})),k.unit==='%'?k.target:null,v=>valueLabel(v,k))}</div><div>${table(['อันดับ','หน่วยบริการ','ผลงาน','สถานะ'],ranking.map((r,i)=>[fmt(i+1),e(r.facility.short_name),e(valueLabel(r.value,k)),badge(kpiStatus(r.value,k))]))}</div></div>`,'เรียงตามทิศทางของตัวชี้วัด • ไม่จัดอันดับหน่วยที่ไม่มีข้อมูล',`<button data-kpi="${k.kpi_id}">นิยามและรายละเอียด</button>`)+panel('รายละเอียดทุกหน่วยบริการ',metricTable(rows,k),'',`<button data-export-hdc="${k.kpi_id}">ส่งออก CSV</button>`) + kpiCards() + (state.route==='service'?serviceStatsPanel():'');}
function serviceStatsPanel(){const rows=profileRows('hp_service_stats');const types=[...new Set(rows.map(r=>r.service_name))];return panel('สถิติบริการอื่นของ Hospital Profile',table(['หน่วยบริการ',...types],facilities().map(f=>[e(f.short_name),...types.map(name=>fmt(sum(rows.filter(r=>r.facility_code===f.facility_code&&r.service_name===name).map(r=>r.visit_count))))])),'ข้อมูลจาก Hospital Profile แยกจาก HDC; ยังไม่มีรายการแพทย์แผนไทย/กายภาพในข้อมูลเดิมที่นำเข้า');}
function metricTable(rows,k){const prev=recordSet(k,true);return table(['หน่วยบริการ','ตัวตั้ง','ตัวหาร','ผลงาน','ผลต่างจากเป้า','ปีก่อน','YoY (ผลต่าง)','ข้อมูลถึงวันที่'],rows.map(r=>{const old=prev.find(p=>p.facility.facility_code===r.facility.facility_code)?.value??null;return [`<button class="table-link" data-profile="${r.facility.facility_code}">${e(r.facility.facility_name)}</button>`,r.eligible?fmt(r.numerator):'N/A',r.eligible?fmt(r.denominator):'N/A',r.eligible?e(valueLabel(r.value,k)):badge({key:'na',text:'N/A – ไม่อยู่ในกลุ่มประเมิน'}),r.value!==null&&k.target!==null?fmt(r.value-k.target,1)+' จุดร้อยละ':'—',r.eligible?e(valueLabel(old,k)):'N/A',r.value!==null&&old!==null?`${r.value-old>=0?'+':''}${fmt(r.value-old,1)} ${k.unit==='%'?'จุดร้อยละ':k.unit}`:'—',e(formatSourceDate(r.source_date))];}));}
function heatmap(){const list=kpis();const units=state.facilities.filter(f=>state.facility==='all'||f.facility_code===state.facility);return panel('สถานะ KPI รายหน่วยบริการ',table(['ตัวชี้วัด',...units.map(f=>f.short_name)],list.map(k=>{const rows=recordSet(k);return [e(k.name),...units.map(f=>{const r=rows.find(x=>x.facility.facility_code===f.facility_code);const status=r?.eligible?kpiStatus(r.value,k):{key:'na',text:'N/A – ไม่อยู่ในกลุ่มประเมิน'};return `<button class="heat-cell ${status.key}" data-kpi="${k.kpi_id}" data-detail-facility="${f.facility_code}" aria-label="${e(k.name+' '+f.short_name+' '+status.text)}">${r?.eligible?fmt(r.value,k.unit==='%'?1:0):'N/A'}<br><small>${e(status.text)}</small></button>`;})];})), 'สีพร้อมข้อความสถานะ • คลิกช่องเพื่อดูตัวตั้ง ตัวหาร และแหล่งข้อมูล');}
function trend(){
 const k=currentKpi();const rows=recordSet(k).filter(r=>r.eligible);const old=recordSet(k,true).filter(r=>r.eligible);
 const quarterly=!rows.some(r=>r.series?.some(p=>p.value!==null))&&rows.some(r=>r.quarters?.some(p=>p.value!==null));
 const key=quarterly?'quarters':'series';const labels=quarterly?['ไตรมาส 1','ไตรมาส 2','ไตรมาส 3','ไตรมาส 4']:monthNames;
 const combine=list=>labels.map((_,i)=>{const points=list.map(r=>r[key]?.[i]);return k.unit==='%'?percent(sum(points.map(p=>p?.numerator)),sum(points.map(p=>p?.denominator))):sum(points.map(p=>p?.value));});
 const current=combine(rows),prior=combine(old);const delta=(a,b)=>a===null||b===null?'—':k.unit==='%'?fmt(a-b,1)+' จุดร้อยละ':b===0?'— ตัวหารเดิมเป็น 0':fmt((a-b)/b*100,1)+'%';
 return panel(quarterly?'แนวโน้มผลงานรายไตรมาส':'แนวโน้มผลงานรายเดือน',`<div class="controls">${kpiSelect()}</div>${columnChart([{label:`FY${state.year}`,values:current},{label:`FY${state.year-1}`,values:prior}],labels,k.unit==='%'?k.target:null)}${table([quarterly?'ไตรมาส':'เดือน','ปีปัจจุบัน','ช่วงก่อน',quarterly?'QoQ':'MoM','ช่วงเดียวกันปีก่อน','YoY'],current.map((v,i)=>[labels[i],e(valueLabel(v,k)),i?e(valueLabel(current[i-1],k)):'—',i?delta(v,current[i-1]):'—',e(valueLabel(prior[i],k)),delta(v,prior[i])]))}`,'แสดงช่วงเวลาตามที่แหล่งข้อมูลมี; ไม่กระจายยอดรายปีเป็นรายเดือน');
}
function compare(){const units=state.facilities.filter(f=>state.selected.has(f.facility_code));const selectors=`<div class="facility-list">${state.facilities.map(f=>`<label><input type="checkbox" data-compare="${f.facility_code}" ${state.selected.has(f.facility_code)?'checked':''}>${e(f.short_name)}</label>`).join('')}</div>`;if(units.length<2)return selectors+'<div class="notice">เลือกอย่างน้อย 2 หน่วยบริการเพื่อเปรียบเทียบ</div>';const k=currentKpi();const rows=recordSet(k).filter(r=>state.selected.has(r.facility.facility_code));const resource=units.map(f=>{const code=f.facility_code;const pop=data('hp_population').find(r=>r.facility_code===code&&+r.fiscal_year===state.year);const staff=data('hp_staff').filter(r=>r.facility_code===code&&+r.fiscal_year===state.year);const vhv=data('hp_volunteers').find(r=>r.facility_code===code&&+r.fiscal_year===state.year);const budget=sum(profileRows('hp_budget_monthly').filter(r=>r.facility_code===code&&r.review_status==='accepted').map(r=>r.amount));const finance=sum(profileRows('hp_finance_monthly').filter(r=>r.facility_code===code&&r.review_status==='accepted').map(r=>r.amount));const ncd=sum(ncdSummary(profileRows('hp_ncd_monthly').filter(r=>r.facility_code===code)).map(r=>r.total));const cd=sum(profileRows('hp_cd_monthly').filter(r=>r.facility_code===code).map(r=>r.case_count));return [e(f.short_name),f.area_unit?fmt(pop?.population):'N/A',fmt(sum(staff.map(r=>r.staff_count))),fmt(vhv?.volunteer_count),fmt(budget,2),fmt(finance,2),fmt(ncd),fmt(cd)];});return selectors+panel('เปรียบเทียบผลงาน HDC',`<div class="controls">${kpiSelect()}</div>${bars(rows.map(r=>({label:r.facility.short_name,value:r.value})),k.unit==='%'?k.target:null,v=>valueLabel(v,k))}${metricTable(rows,k)}${columnChart(rows.filter(r=>r.eligible).map(r=>({label:r.facility.short_name,values:r.series.map(p=>p.value)})),monthNames,k.unit==='%'?k.target:null)}`)+panel('ทรัพยากรและ Hospital Profile',table(['หน่วยบริการ','ประชากรพื้นที่','บุคลากร','อสม.','งบประมาณ','เบิกจ่าย','NCD','โรคติดต่อ'],resource),'ค่าโรครวมใช้เปรียบเทียบภาระข้อมูล ไม่ใช่จำนวนบุคคลไม่ซ้ำ');}
function profile(){let f=state.facilities.find(f=>f.facility_code===state.facility)??state.facilities[0];const code=f.facility_code;const pop=data('hp_population').find(r=>r.facility_code===code&&+r.fiscal_year===state.year);const staff=data('hp_staff').filter(r=>r.facility_code===code&&+r.fiscal_year===state.year);const vhv=data('hp_volunteers').find(r=>r.facility_code===code&&+r.fiscal_year===state.year);const detail=data('hp_facility_profiles').find(r=>r.facility_code===code);const count=sum(staff.map(r=>r.staff_count));const support=sum(staff.map(r=>r.support_count));const totals={budget:sum(data('hp_budget_monthly').filter(r=>r.facility_code===code&&+r.fiscal_year===state.year&&r.review_status==='accepted').map(r=>r.amount)),finance:sum(data('hp_finance_monthly').filter(r=>r.facility_code===code&&periodMatches(r,state.year,state.period)&&r.review_status==='accepted').map(r=>r.amount))};const ratio=(a,b)=>number(a)!==null&&number(b)>0?'1 : '+fmt(a/b):'—';return panel(f.facility_name,`<div class="link-row"><span class="inline-code">รหัส ${code}</span><span>${f.area_unit?'หน่วยพื้นที่รับผิดชอบ':'หน่วยบริการ ไม่มีประชากรพื้นที่รับผิดชอบ'}</span><span>${e(detail?.address??'ที่อยู่: — ไม่มีข้อมูลต้นทาง')}</span></div>`, '',canEdit(code)?`<button class="primary" data-edit-profile="${code}">แก้ไขข้อมูลพื้นฐาน</button>`:'')+`<div class="grid stats">${stat('ประชากร',f.area_unit?fmt(pop?.population):'N/A','พื้นที่รับผิดชอบ',true)}${stat('หลังคาเรือน',f.area_unit?fmt(pop?.households):'N/A')}${stat('ชุมชน',f.area_unit?fmt(pop?.communities):'N/A')}${stat('เจ้าหน้าที่',fmt(count))}${stat('บุคลากรสนับสนุน',fmt(support))}${stat('อสม.',fmt(vhv?.volunteer_count))}${stat('ประชากรชาย',f.area_unit?fmt(pop?.male):'N/A')}${stat('ประชากรหญิง',f.area_unit?fmt(pop?.female):'N/A')}</div>`+`<div class="grid half-columns">${panel('กำลังคนและสัดส่วนรับผิดชอบ',table(['รายการ','จำนวน'],[['ประชากรต่อเจ้าหน้าที่',f.area_unit?ratio(pop?.population,count):'N/A'],['หลังคาเรือนต่อ อสม.',f.area_unit?ratio(pop?.households,vhv?.volunteer_count):'N/A'],...staff.map(r=>[e(r.profession),fmt(r.staff_count)])]))}${panel('งบประมาณ',table(['รายการ','บาท'],[['แผนที่ยืนยันแล้ว',fmt(totals.budget,2)],['เบิกจ่าย',fmt(totals.finance,2)],['คงเหลือ',totals.budget!==null&&totals.finance!==null?fmt(totals.budget-totals.finance,2):'—'],['ร้อยละเบิกจ่าย',fmt(percent(totals.finance,totals.budget),2)+'%']]))}</div>`+panel('HDC Performance',table(['ตัวชี้วัด','ตัวตั้ง','ตัวหาร','ผลงาน','สถานะ'],state.kpis.filter(published).map(k=>{const r=recordSet(k).find(r=>r.facility.facility_code===code);return [`<button class="table-link" data-kpi="${k.kpi_id}" data-detail-facility="${code}">${e(k.name)}</button>`,r?.eligible?fmt(r.numerator):'N/A',r?.eligible?fmt(r.denominator):'N/A',r?.eligible?e(valueLabel(r.value,k)):'N/A',r?.eligible?badge(kpiStatus(r.value,k)):badge({key:'na',text:'N/A – ไม่อยู่ในกลุ่มประเมิน'})];})))+panel('โรคเรื้อรังและโรคติดต่อ',table(['กลุ่ม','โรค','จำนวน'],[...ncdSummary(data('hp_ncd_monthly').filter(r=>r.facility_code===code&&periodMatches(r,state.year,state.period))).map(r=>['NCD',e(r.disease),fmt(r.total)]),...data('hp_cd_monthly').filter(r=>r.facility_code===code&&periodMatches(r,state.year,state.period)).map(r=>['โรคติดต่อ',e(r.disease),fmt(r.case_count)])]),'จำนวนรวมรายโรคอาจนับคนเดียวในหลายโรคได้')+panel('ข้อมูลเพิ่มเติม',e(detail?.notes??'— ยังไม่มีข้อมูลเพิ่มเติม'),'วันที่ข้อมูลพื้นฐานต้นทาง: '+formatSourceDate(pop?.source_updated_at));}
function finance(){const units=facilities();const rows=units.map(f=>{const budget=sum(profileRows('hp_budget_monthly').filter(r=>r.facility_code===f.facility_code&&r.review_status==='accepted').map(r=>r.amount));const spent=sum(profileRows('hp_finance_monthly').filter(r=>r.facility_code===f.facility_code&&r.review_status==='accepted').map(r=>r.amount));return {f,budget,spent,remaining:budget!==null&&spent!==null?budget-spent:null,rate:percent(spent,budget)};});const totals=summaryTotals();const monthly=fiscalMonths.map(m=>sum(profileRows('hp_finance_monthly').filter(r=>+r.period.slice(5,7)===m&&r.review_status==='accepted').map(r=>r.amount)));const pending=profileRows('hp_budget_monthly').filter(r=>r.review_status==='pending');const content=`<div class="grid stats">${stat('แผนเงินที่ยืนยันแล้ว',fmt(totals.budget,2),'บาท',true)}${stat('เบิกจ่าย',fmt(totals.finance,2),'บาท')}${stat('คงเหลือ',totals.budget!==null&&totals.finance!==null?fmt(totals.budget-totals.finance,2):'—','บาท')}${stat('ร้อยละเบิกจ่าย',fmt(percent(totals.finance,totals.budget),2)+'%','เทียบแผนเงินทั้งปี')}</div>`;return (pending.length?`<div class="notice">มีแผนเงิน ${pending.length} รายการรอตรวจสอบ ไม่รวมในยอดที่ยืนยันแล้ว • ข้อมูลแผนรายปีไม่มีปีระบุ ต้นทางชุดนี้อนุมานเป็น FY2569</div>`:'')+content+panel('งบประมาณรายหน่วยบริการ',table(['หน่วยบริการ','แผนทั้งปี','เบิกจ่าย','คงเหลือ','ร้อยละ'],rows.map(r=>[`<button class="table-link" data-finance="${r.f.facility_code}">${e(r.f.short_name)}</button>`,fmt(r.budget,2),fmt(r.spent,2),fmt(r.remaining,2),fmt(r.rate,2)+'%'])),'คลิกชื่อหน่วยเพื่อดูยอดจ่ายรายเดือน',`<button data-export="finance">ส่งออก CSV</button>`)+panel('ร้อยละการเบิกจ่ายสะสม เปรียบเทียบรายหน่วยบริการ',columnChart([{label:'เบิกจ่าย (%)',values:rows.map(r=>r.rate)}],rows.map(r=>r.f.short_name),80),'เส้นประ: เป้าหมายบริหาร 80% ตามที่ผู้ดูแลกำหนด')+panel('แนวโน้มการเบิกจ่าย',columnChart([{label:'ยอดจ่าย (บาท)',values:monthly}],monthNames))+panel('ยอดเบิกจ่ายรายเดือน',table(['เดือน',...units.map(f=>f.short_name),'รวม'],fiscalMonths.map((m,i)=>[monthNames[i],...units.map(f=>fmt(sum(profileRows('hp_finance_monthly').filter(r=>r.facility_code===f.facility_code&&+r.period.slice(5,7)===m&&r.review_status==='accepted').map(r=>r.amount)),2)),fmt(monthly[i],2)])),'ช่องว่างหมายถึงไม่มีรายการเดือนนั้น ไม่ถือเป็นศูนย์');}
function diseaseView(kind){return (kind==='ncd'?ncdView:cdView)({rows:data(kind==='ncd'?'hp_ncd_monthly':'hp_cd_monthly'),population:data('hp_population'),units:facilities(),year:state.year,period:state.period,rate:state.rateMode,panel,table});}
function quality(){const failures=state.kpis.filter(k=>state.hdc[k.kpi_id]?.error);const missing=state.kpis.flatMap(k=>recordSet(k).filter(r=>r.eligible&&r.value===null).map(r=>({k,r})));const unresolved=data('hp_data_quality').filter(r=>!r.resolved);const rows=state.kpis.map(k=>{const response=state.hdc[k.kpi_id];const records=recordSet(k);const eligibleRows=records.filter(r=>r.eligible);const noDen=eligibleRows.filter(r=>r.missing_denominator);const age=response?.source_date?Date.now()-Date.parse(String(response.source_date).replace(/^(\d{4})(\d{2})(\d{2}).*$/,'$1-$2-$3T00:00:00+07:00')):null;return [e(k.name),badge(response?.error?{key:response.stale?'near':'low',text:response.stale?'ข้อมูลแคช • API ขัดข้อง':'API ขัดข้อง'}:{key:'pass',text:'✓ API ตอบสำเร็จ'}),`${eligibleRows.filter(r=>r.value!==null).length}/${eligibleRows.length}`,fmt(noDen.length),e(formatSourceDate(response?.source_date)),response?.fetched_at?e(formatSourceDate(response.fetched_at)):'—',age!==null&&age>runtime.staleDays*86400000?'ข้อมูลเกิน 30 วัน':'—',e(response?.error??'')];});return `<div class="grid stats">${stat('API มีปัญหา',fmt(failures.length))}${stat('KPI / หน่วยขาดข้อมูล',fmt(missing.length))}${stat('รายการรอตรวจสอบ',fmt(unresolved.length))}${stat('Hospital Profile',state.profile.errors.length?'เชื่อมต่อบางส่วน':'เชื่อมต่อแล้ว')}</div>`+panel('สถานะ HDC และความครบถ้วน',table(['ตัวชี้วัด','สถานะ','มีข้อมูล','ขาดตัวหาร / ตัวหาร 0','วันที่ข้อมูล','ดึงสำเร็จล่าสุด','ความเก่า','รายละเอียด'],rows))+panel('ข้อมูล Hospital Profile ที่ต้องตรวจสอบ',table(['หน่วยบริการ','ประเภท','รายละเอียด','สถานะ'],data('hp_data_quality').map(r=>[e(r.facility_code),e(r.issue_type),e(r.detail),r.resolved?'✓ ตรวจสอบแล้ว':'! รอตรวจสอบ'])),'วันที่ต้นทางของชุดเดิมไม่ระบุ; เวลาย้ายข้อมูลไม่ใช่วันที่ข้อมูลอัปเดต')+panel('ตรวจ master หน่วยบริการ',table(['รหัส','หน่วยบริการ','พื้นที่','บริการ'],state.facilities.map(f=>[e(f.facility_code),e(f.facility_name),f.area_unit?'✓ มีพื้นที่':'N/A',f.service_unit?'✓ บริการ':'—'])))+panel('ทะเบียนรายงาน HDC เดิม',`<details><summary>ตรวจรายการรายงาน ${state.inventory.length} รายการ</summary>${table(['ตาราง','รายงาน','สถานะ'],state.inventory.map(r=>[e(r.table),r.source_url?`<a href="${e(r.source_url)}" target="_blank" rel="noopener">${e(r.title)}</a>`:e(r.title),r.integrated?'เชื่อมในระบบใหม่':'นิยามเดิม • ยังไม่รวมการคำนวณใหม่']))}</details>`,'รายการที่ยังไม่ยืนยัน scope/สูตรจะไม่ถูกนำมาประเมิน KPI อัตโนมัติ');}
function manage(){return '<p><a href="#personnel">♧ จัดการบุคลากรและรูปภาพ →</a></p>'+panel('เวอร์ชันและประวัติการปรับปรุง','<p class="release-credit">'+e(credit)+'</p>'+table(['เวอร์ชัน','วันที่','รายละเอียด'],release.history.map(r=>[e(r.version),e(r.date),e(r.description)])))+(admin()?'<p><a href="#kpi-admin">☑ จัดการการแสดงผล KPI (ADMIN) →</a></p>':'')+(admin()?accountPanel():'')+manageData();}
function manageData(){if(!currentSession())return panel('เข้าสู่ระบบเพื่อจัดการข้อมูล','<p>ใช้บัญชี Supabase ของโครงการ med-device-sharing เจ้าหน้าที่แก้ไขได้เฉพาะหน่วยที่ได้รับมอบหมาย</p><button id="manage-login" class="primary">เข้าสู่ระบบ</button><p class="subtle">บัญชี Hospital Profile เดิมยังใช้กับระบบเดิมได้ รหัสผ่านเดิมไม่ได้ย้ายเข้า Supabase</p>');if(!state.permissions.length)return panel('บัญชีนี้ยังไม่ได้รับมอบหมายหน่วยบริการ',`<p>แจ้งรหัสผู้ใช้ต่อผู้ดูแลระบบเพื่อกำหนดสิทธิ์</p><p class="inline-code">${e(currentSession().user.id)}</p>`);const labels=Object.entries(tableLabels).filter(([name])=>admin()||!['hp_settings','hp_data_quality'].includes(name));const list=data(state.manageTable).filter(r=>state.manageTable!=='hp_settings'||r.category!=='kpi_publication').filter(r=>(!r.facility_code||canEdit(r.facility_code))&&(!r.fiscal_year||periodMatches(r,state.year,state.period))&&(state.facility==='all'||!r.facility_code||r.facility_code===state.facility)).filter(r=>!state.search||JSON.stringify(r).toLowerCase().includes(state.search.toLowerCase()));const keys=['facility_code','period','fiscal_year','disease','case_type','profession','staff_count','support_count','amount','case_count','visit_count','service_name','review_status','detail','resolved','category','setting_key'].filter(k=>list.some(r=>k in r));const heading=['หน่วยบริการ','เดือน','ปีงบประมาณ','โรค','ประเภทราย','วิชาชีพ','บุคลากร','สนับสนุน','ยอดเงิน','จำนวนราย','จำนวนครั้ง','บริการ','สถานะตรวจสอบ','รายละเอียด','แก้ไขแล้ว','หมวด','รหัสตั้งค่า'];const headings=keys.map(k=>heading[['facility_code','period','fiscal_year','disease','case_type','profession','staff_count','support_count','amount','case_count','visit_count','service_name','review_status','detail','resolved','category','setting_key'].indexOf(k)]);return panel('เพิ่มและแก้ไขข้อมูล',`<div class="controls"><label>ประเภทข้อมูล<select id="manage-table">${labels.map(([name,label])=>`<option value="${name}" ${state.manageTable===name?'selected':''}>${e(label)}</option>`).join('')}</select></label><label>ค้นหารายการ<input id="manage-search" value="${e(state.search)}" placeholder="รหัสหน่วย / ชื่อโรค / เดือน"></label><button id="add-record" class="primary">+ เพิ่มรายการ</button><button data-export="manage">ส่งออก CSV</button></div>${table([...headings,'จัดการ'],list.slice(0,300).map(r=>[...keys.map(k=>e(r[k])),`<button data-edit-record="${e(r.id??r.setting_key)}">แก้ไข</button> <button class="danger" data-delete-record="${e(r.id??r.setting_key)}">ลบ</button>`]))}<p class="subtle">${list.length} รายการ • ประวัติการเปลี่ยนแปลงบันทึกใน Audit Log</p>`, 'สิทธิ์ตรวจสอบโดย RLS ในฐานข้อมูลทุกครั้ง')+(admin()?panel('สิทธิ์ผู้ใช้งาน',`<p class="subtle">ใช้รหัส UUID ของบัญชี Supabase ที่มีอยู่ การกำหนด ADMIN จะให้สิทธิ์ครบทุกหน่วย</p><form id="permissions-form" class="form-grid"><label>รหัสผู้ใช้ (UUID)<input name="user_id" required pattern="[0-9a-fA-F-]{36}"></label><label>หน่วยบริการ<select name="facility_code">${state.facilities.map(f=>`<option value="${f.facility_code}">${e(f.short_name)}</option>`).join('')}</select></label><label>สิทธิ์<select name="role"><option>STAFF</option><option>ADMIN</option></select></label><button type="submit" class="primary">บันทึกสิทธิ์</button><div class="form-error" id="permissions-error"></div></form>${table(['ผู้ใช้','หน่วย','สิทธิ์','จัดการ'],state.permissions.map(p=>[e(p.user_id),e(p.facility_code),e(p.role),`<button class="danger" data-revoke-user="${p.user_id}" data-revoke-code="${p.facility_code}">ถอนสิทธิ์</button>`]))}<button id="audit-view">ดูประวัติการเปลี่ยนแปลง</button>`):'');}
function updateFilters(){const allowed=state.facilities.filter(f=>state.scope!=='AREA'||f.area_unit);if(state.facility!=='all'&&!allowed.some(f=>f.facility_code===state.facility))state.facility='all';$('facility').innerHTML='<option value="all">ทุกหน่วยบริการ</option>'+allowed.map(f=>`<option value="${f.facility_code}" ${state.facility===f.facility_code?'selected':''}>${e(f.short_name)}</option>`).join('');$('scope').value=state.scope;}


async function accountApi(body){if(!admin())throw new Error('เฉพาะ ADMIN เท่านั้น');await refreshSession();return request(runtime.supabaseUrl+'/functions/v1/hp-accounts',{method:'POST',headers:{apikey:runtime.supabaseKey,Authorization:'Bearer '+currentSession().access_token,'Content-Type':'application/json'},body:JSON.stringify(body)});}
function accountPanel(){return panel('สร้างบัญชีเฉพาะ Hospital Profile','<p>บัญชีใหม่มีสิทธิ์เฉพาะเว็บนี้ ไม่อนุมัติสิทธิ์ระบบยืมอุปกรณ์หรือระบบอื่น เข้าสู่ระบบด้วยอีเมลและรหัสผ่านที่กำหนด</p><form id="create-account-form"><div class="form-grid"><label>ชื่อผู้ใช้/ชื่อเจ้าหน้าที่<input name="name" required maxlength="100" autocomplete="off"></label><label>อีเมลสำหรับเข้าสู่ระบบ<input name="email" type="email" required autocomplete="off"></label><label>รหัสผ่านใหม่ (อย่างน้อย 12 ตัวอักษร)<input name="password" type="password" minlength="12" maxlength="128" required autocomplete="new-password"></label><label>สิทธิ์<select name="role"><option>STAFF</option><option>ADMIN</option><option>USER</option></select></label></div><p class="subtle">USER เปลี่ยนรูปตนเองหลัง ADMIN เชื่อมบัญชี ไม่ต้องเลือกหน่วย • STAFF เลือกหน่วยที่ดูแล • ADMIN มีสิทธิ์ทุกหน่วยใน Hospital Profile</p><div class="facility-list">'+state.facilities.map(f=>'<label><input type="checkbox" name="account_facility" value="'+f.facility_code+'">'+e(f.short_name)+'</label>').join('')+'</div><div id="account-error" class="form-error" role="status">'+e(state.accountNotice??'')+'</div><button type="submit" class="primary">สร้างบัญชี</button></form><div class="controls"><button id="load-hp-accounts">โหลดรายชื่อบัญชีเว็บนี้</button></div>'+table(['ชื่อ','อีเมล','รหัสบัญชี (UUID)','หน่วย/สิทธิ์','รหัสผ่าน'],(state.hpAccounts??[]).map(a=>[e(a.name),e(a.email),'<span class="inline-code">'+e(a.id)+'</span>',e(a.permissions.map(p=>p.facility_code+' '+p.role).join(', ')||a.role||'USER'), '<button data-reset-account="'+a.id+'">ตั้งรหัสผ่านใหม่</button>'])),'บัญชีร่วมเดิมของระบบอื่นไม่แสดงในรายการนี้ และเปลี่ยนรหัสผ่านผ่านหน้านี้ไม่ได้');}

function kpiAdmin(){
 if(!currentSession())return panel('จัดการ KPI สำหรับ ADMIN','<p>เข้าสู่ระบบด้วยบัญชี ADMIN เพื่อกำหนดการแสดงผล KPI</p><button id="manage-login" class="primary">เข้าสู่ระบบ</button>');
 if(!admin())return panel('จัดการ KPI สำหรับ ADMIN','<p>บัญชีนี้ไม่มีสิทธิ์จัดการการแสดงผล KPI</p>');
 const rows=state.kpis.map(k=>{const setting=publicationSetting(data('hp_settings'),k.kpi_id,state.year);const status=dataStatus(state.hdc[k.kpi_id],recordSet(k));const check=setting.last_check;return [e(k.name)+'<div class="subtle">'+e(k.scope)+' • '+e(k.table)+'</div>',badge({key:status.available?'pass':status.key==='error'?'low':'near',text:status.text}),status.available+'/'+status.expected,e(formatSourceDate(state.hdc[k.kpi_id]?.source_date)),check?e(formatSourceDate(check.checked_at))+'<div class="subtle">'+e(check.error??'API ตอบสำเร็จ')+'</div>':'ยังไม่ได้ตรวจ API สด',published(k)?'✓ แสดงในช่วงนี้':'พักการแสดงผล', '<label class="kpi-toggle"><input type="checkbox" data-publish-kpi="'+k.kpi_id+'" '+(setting.mode!=='hide'?'checked':'')+' '+(state.kpiBusy?'disabled':'')+'>อนุญาตให้แสดง</label><div class="subtle">'+(setting.mode==='auto'?'อัตโนมัติ':setting.mode==='hide'?'แอดมินซ่อนไว้':'แอดมินเปิดไว้')+'</div><button data-auto-kpi="'+k.kpi_id+'" '+(state.kpiBusy?'disabled':'')+'>อัตโนมัติ</button>', '<button data-check-kpi="'+k.kpi_id+'" '+(state.kpiBusy||state.loading?'disabled':'')+'>ตรวจ API สด</button>'];});
 return panel('กำหนด KPI ที่แสดงต่อผู้บริหาร', '<p>ตั้งค่าสำหรับปี '+state.year+' • เลือกปี/ช่วงเวลาจากตัวกรองด้านบน การซ่อนจะมีผลกับทุกคนในปีนี้</p><p>เปิดไว้จะแสดงเมื่อมีค่าที่ใช้ได้ในช่วงเวลาที่เลือก ค่า 0 จริงยังแสดง และข้อมูลแคชที่ใช้ได้ยังแสดงเมื่อ API ขัดข้อง รายการที่ไม่มีค่าจะพักไว้ชั่วคราวและกลับมาแสดงเมื่อมีข้อมูล</p><div class="controls"><button id="check-all-kpi" '+(state.kpiBusy||state.loading?'disabled':'')+'>ตรวจ API สดทุก KPI ทีละรายการ</button><button id="stop-kpi-check" '+(!state.kpiBusy?'disabled':'')+'>หยุดตรวจ</button></div><div role="status" class="notice">'+e(state.kpiAdminNotice??'การตั้งค่าบันทึกลงระบบกลาง และเก็บประวัติการเปลี่ยนแปลง')+'</div>'+table(['KPI','สถานะข้อมูลช่วงที่เลือก','หน่วยมีค่า','วันที่ข้อมูล','ตรวจ API สดล่าสุด','ผลการแสดง','เปิด / ซ่อน','ตรวจสอบ'],rows));
}
async function savePublication(id,changes,year=state.year){
 if(!admin())throw new Error('เฉพาะ ADMIN เท่านั้น');
 const key=publicationKey(id,year);const existing=await rest('hp_settings','setting_key=eq.'+encodeURIComponent(key));
 const value={...(existing[0]?.value??{mode:'auto'}),...changes};
 if(existing.length)await rest('hp_settings','setting_key=eq.'+encodeURIComponent(key),'PATCH',{value});
 else try{await rest('hp_settings','','POST',{setting_key:key,category:'kpi_publication',value});}catch(error){if(error.status!==409)throw error;await rest('hp_settings','setting_key=eq.'+encodeURIComponent(key),'PATCH',{value});}
 const rows=data('hp_settings');const i=rows.findIndex(r=>r.setting_key===key);const row={setting_key:key,category:'kpi_publication',value};if(i>=0)rows[i]=row;else rows.push(row);
}
async function checkPublication(ids){
 if(!admin())throw new Error('เฉพาะ ADMIN เท่านั้น');if(state.kpiBusy)return;
 const year=state.year;const generation=state.generation;state.kpiBusy=true;state.stopKpi=false;
 try{for(let i=0;i<ids.length;i++){if(state.stopKpi||generation!==state.generation)break;const k=state.kpis.find(k=>k.kpi_id===ids[i]);state.kpiAdminNotice='กำลังตรวจ '+(i+1)+'/'+ids.length+' • '+k.name;render();const response=await fetchHdc(k,year,state.facilities,true,true);const records=facilityResults(response.rows??[],k,state.facilities);const status=dataStatus(response,records);await savePublication(k.kpi_id,{last_check:{checked_at:new Date().toISOString(),error:response.error??null,source_date:response.source_date??null,rows:response.rows?.length??0,available_units:status.available,expected_units:status.expected}},year);if(generation===state.generation)state.hdc[k.kpi_id]=response;state.kpiAdminNotice='ตรวจ '+(i+1)+'/'+ids.length+' • '+k.name+': '+status.text;render();if(i+1<ids.length&&!state.stopKpi)await new Promise(resolve=>setTimeout(resolve,3000));}state.kpiAdminNotice=state.stopKpi?'หยุดตรวจแล้ว รายการที่ตรวจเสร็จถูกบันทึกไว้':'ตรวจเสร็จแล้ว • เลือกเปิดหรือซ่อน KPI ได้';}
 finally{state.kpiBusy=false;render();}
}

function render(){
 const route=routes.find(r=>r[0]===state.route)??routes[0];$('page-title').textContent=route[2];$('page-description').textContent=state.route==='area'?'เปรียบเทียบเฉพาะหน่วยที่มีประชากรพื้นที่รับผิดชอบ 7 แห่ง':state.route==='service'?'ผลงานบริการครบ 8 หน่วย รวม ศบส.เขลางค์นคร':'ระบบติดตามและเปรียบเทียบผลงานสุขภาพ หน่วยบริการสังกัดเทศบาลเมืองเขลางค์นคร';document.title=route[2]+' | Kelang Health Performance';document.querySelectorAll('#navigation a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+state.route);if(a.hash==='#'+state.route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 updateFilters();const responses=Object.values(state.hdc);const latest=responses.map(r=>r.source_date).filter(Boolean).sort().at(-1);const fetched=responses.map(r=>r.fetched_at).filter(Boolean).sort().at(-1);const stale=responses.some(r=>r.stale);$('freshness').innerHTML=`<span>ข้อมูล HDC ถึงวันที่: ${e(formatSourceDate(latest))}</span><span>อัปเดตระบบล่าสุด: ${e(formatSourceDate(fetched))}</span><span>Hospital Profile ต้นทาง: ไม่ระบุวันที่</span>${stale?'<span class="badge near">ข้อมูลล่าสุดที่มี • มี API ขัดข้อง</span>':''}`;
 $('connection').textContent=state.loading?'กำลังอ่าน HDC':responses.some(r=>r.error)?'HDC เชื่อมต่อบางส่วน':state.profile.errors.length?'เชื่อมต่อบางส่วน':'เชื่อมต่อข้อมูลจริง';$('auth-button').textContent=currentSession()?'ออกจากระบบ':'เข้าสู่ระบบ';$('refresh').disabled=state.loading;
 const viewFns={overview,units:unitPortal,personnel:()=>personnelView({rows:()=>data('hp_personnel'),links:()=>state.personnelLinks??[],permissions:()=>state.permissions,facilities:()=>state.facilities,facility:()=>state.facility,render,dialog:openDialog,closeDialog:()=>$('dialog').close(),reload:reloadProfile}),area:performance,service:performance,heatmap,trend,compare,profile,finance,ncd:()=>diseaseView('ncd'),cd:()=>diseaseView('cd'),quality,manage,'kpi-admin':kpiAdmin};$('view').innerHTML=['area','service','heatmap','trend','compare'].includes(state.route)&&!kpis().length?panel(state.year===2570?'อยู่ระหว่างรอข้อมูลปีงบประมาณ 2570':'ยังไม่มี KPI ที่พร้อมแสดง',state.year===2570?'<p>อยู่ระหว่างรอข้อมูลจากหน่วยบริการ คาดว่าจะเริ่มประมวลผลและแสดงข้อมูลช่วง 15–20 พฤศจิกายน 2569 ตามข้อมูลที่ผู้ดูแลแจ้ง ระหว่างนี้ให้ดูข้อมูลปีงบประมาณ 2569 ไปก่อน</p>':'<p>ปีหรือช่วงเวลาที่เลือกยังไม่มีข้อมูลที่คำนวณได้ หรือผู้ดูแลพักการแสดงผลไว้ กรุณาเลือกปีหรือช่วงเวลาอื่น</p>'):(viewFns[state.route]??overview)();$('view').setAttribute('aria-busy',String(state.loading));if(state.route==='personnel'||state.route==='units')void mountPersonnel();
 const errors=state.profile.errors;$('message').innerHTML=errors.length?`<div class="notice error">Hospital Profile เชื่อมต่อไม่ครบ: ${errors.map(r=>e(r.table+' '+r.error)).join(' • ')} ข้อมูลบางส่วนอาจไม่ปรากฏ</div>`:state.loading?'<div class="notice">กำลังอ่านข้อมูล HDC ของปีที่เลือกและช่วงเดียวกันปีก่อน… ข้อมูลหน่วยบริการพร้อมใช้งานแล้ว</div>':state.hdcNotice?'<div class="notice" role="status">'+e(state.hdcNotice)+'</div>':responses.some(r=>r.error)?'<div class="notice">HDC บางรายการอ่าน API ล่าสุดไม่สำเร็จ แสดงชุดข้อมูลจริงล่าสุดที่มี • ดูรายละเอียดที่เมนูคุณภาพข้อมูล หรือเลือก KPI แล้วกดดึง API สด</div>':'';
}
async function load(force=false){const generation=++state.generation;state.loading=true;state.hdcNotice='';render();try{const profile=await loadProfile();if(generation!==state.generation)return;state.profile=profile;if(data('hp_facilities').length)state.facilities=data('hp_facilities').sort((a,b)=>a.display_order-b.display_order);await loadPermissions();render();const hdc=await fetchGroup(state.kpis,state.year,state.facilities,force);if(generation!==state.generation)return;state.hdc=hdc;render();const previous=await fetchGroup(state.kpis,state.year-1,state.facilities,force);if(generation!==state.generation)return;state.previous=previous;}catch(error){if(generation===state.generation)$('message').innerHTML=`<div class="notice error">${e(error.message)}</div>`;}finally{if(generation===state.generation){state.loading=false;render();}}}
async function loadPermissions(){await refreshSession();state.permissions=currentSession()?await readAll('hp_user_facilities'):[];state.personnelLinks=currentSession()?await readAll('hp_personnel_accounts'):[];}
function navigate(){const selected=parseUnitHash(location.hash,state.facilities);const route=location.hash.slice(1).split('?')[0];state.unitCode=selected?.code??null;state.unitTab=selected?.tab??'home';state.route=selected?'units':routes.some(r=>r[0]===route)?route:'overview';state.scope=state.route==='area'?'AREA':state.route==='service'?'SERVICE':'all';state.facility=selected?.code??(state.route==='units'?'all':state.facility);state.category='all';$('category').value='all';updateFilters();render();closeSidebar(false);}
function unitPortal(){return unitsView({units:()=>state.facilities,code:()=>state.unitCode,tab:()=>state.unitTab,rows:()=>data('hp_unit_public_info'),admin,canEdit,reload:reloadProfile,resources:profile,performance:()=>kpis().length?performance():panel('ผลงานของหน่วย','<div class="empty">ยังไม่มี KPI ที่พร้อมแสดงสำหรับหน่วย ปี และช่วงเวลาที่เลือก</div>'),team:code=>panel('บุคลากรของหน่วย',unitPersonnel({rows:()=>data('hp_personnel').filter(p=>p.facility_code===code&&p.active&&p.published),links:()=>[],permissions:()=>[],facilities:()=>state.facilities.filter(f=>f.facility_code===code),facility:()=>code,render,reload:reloadProfile,dialog:openDialog,closeDialog:()=>$('dialog').close()}))});}

function openDialog(title,body){$('dialog-title').textContent=title;$('dialog-body').innerHTML=body;$('dialog').showModal();}
function detailKpi(id,code){const k=state.kpis.find(k=>k.kpi_id===id);const rows=recordSet(k).filter(r=>!code||r.facility.facility_code===code);const response=state.hdc[id];const sourceLink=k.source_url?`<a href="${e(k.source_url)}" target="_blank" rel="noopener">เปิดนิยาม HDC →</a>`:'';openDialog(k.name,`<p>${k.scope==='AREA'?'ประเมิน 7 หน่วยพื้นที่':'ผลงานบริการ 8 หน่วย'} • ${state.year} • ${e($('period').selectedOptions[0].text)}</p><p class="subtle">${e(k.note)}<br>สูตร: ${k.unit==='%'?e(k.numerator_field+' / '+k.denominator_field+' × '+k.rate):e(k.numerator_field+' (จำนวนบริการ)')}</p>${sourceLink}${response?.error?`<div class="notice">${e(response.error)}${response.stale?' • กำลังแสดงข้อมูลล่าสุดที่มี ณ '+e(formatSourceDate(response.source_date)):''}</div>`:''}${metricTable(rows,k)}<div class="subtle">ข้อมูล HDC ถึงวันที่ ${e(formatSourceDate(response?.source_date))}</div>`);}
function openLogin(){openDialog('เข้าสู่ระบบเจ้าหน้าที่',`<form id="login-form"><p>บัญชี Supabase ในโครงการ med-device-sharing</p><label>อีเมล<input name="email" type="email" autocomplete="username" required></label><label style="margin-top:15px">รหัสผ่าน<input name="password" type="password" autocomplete="current-password" required></label><div class="form-error" id="login-error"></div><div class="form-actions"><button class="primary" type="submit">เข้าสู่ระบบ</button></div><p class="subtle">บัญชี Hospital Profile เดิมใช้กับ <a href="${runtime.legacyUrl}" target="_blank" rel="noopener">ระบบเดิม</a> ได้ตามเดิม</p></form>`);}
function field(label,name,value,type='number',extra=''){return `<label>${e(label)}<input name="${e(name)}" type="${type}" value="${e(value??'')}" ${type==='number'?`min="0" ${extra.includes('step=')?'':'step="1"'}`:''} ${extra}></label>`;}
function profileForm(code){if(!canEdit(code))throw new Error('ไม่ได้รับสิทธิ์แก้ไขหน่วยนี้');const p=data('hp_population').find(r=>r.facility_code===code&&+r.fiscal_year===state.year)??{};const s=data('hp_staff').find(r=>r.facility_code===code&&+r.fiscal_year===state.year&&r.profession==='รวมบุคลากร')??{};const v=data('hp_volunteers').find(r=>r.facility_code===code&&+r.fiscal_year===state.year)??{};const f=data('hp_facility_profiles').find(r=>r.facility_code===code)??{};openDialog('แก้ไขข้อมูลพื้นฐาน '+code,`<form id="profile-form" data-code="${code}"><p>ปีงบประมาณ ${state.year} • เว้นว่างได้หากยังไม่มีข้อมูล</p><div class="form-grid">${[['ประชากร','population',p.population],['ชาย','male',p.male],['หญิง','female',p.female],['หลังคาเรือน','households',p.households],['ชุมชน','communities',p.communities],['เจ้าหน้าที่','staff_count',s.staff_count],['บุคลากรสนับสนุน','support_count',s.support_count],['อสม.','volunteer_count',v.volunteer_count]].map(a=>field(...a)).join('')}${field('ที่อยู่','address',f.address,'text')}${field('ข้อมูลเพิ่มเติม','notes',f.notes,'text')}</div><div id="profile-error" class="form-error"></div><div class="form-actions"><button type="submit" class="primary">บันทึกข้อมูล</button></div></form>`);}
function recordForm(id){const tableName=state.manageTable;const r=id?data(tableName).find(r=>(r.id??r.setting_key)===id):{};if(!r)throw new Error('ไม่พบข้อมูลรายการ');if(r.facility_code&&!canEdit(r.facility_code))throw new Error('ไม่ได้รับสิทธิ์แก้ไข');const numericFields={hp_finance_monthly:['ยอดเงิน (บาท)','amount'],hp_budget_monthly:['ยอดเงิน (บาท)','amount'],hp_ncd_monthly:['จำนวนราย','case_count'],hp_cd_monthly:['จำนวนราย','case_count'],hp_service_stats:['จำนวนครั้ง','visit_count'],hp_staff:['จำนวนบุคลากร','staff_count']};let fields='';if(!['hp_settings','hp_data_quality'].includes(tableName)){fields=`<label>หน่วยบริการ<select name="facility_code" required>${state.facilities.filter(f=>canEdit(f.facility_code)).map(f=>`<option value="${f.facility_code}" ${r.facility_code===f.facility_code?'selected':''}>${e(f.short_name)}</option>`).join('')}</select></label>${field('ปีงบประมาณ','fiscal_year',r.fiscal_year??state.year,'number','required')}`;if(tableName!=='hp_staff')fields+=field('ประจำเดือน','period',r.period?.slice(0,7)??`${state.year-543}-01`,'month',tableName==='hp_budget_monthly'?'':'required');const numeric=numericFields[tableName];if(numeric)fields+=field(numeric[0],numeric[1],r[numeric[1]],'number',`required ${numeric[1]==='amount'?'step="0.01"':''}`);if(['hp_ncd_monthly','hp_cd_monthly'].includes(tableName))fields+=field('โรค','disease',r.disease,'text','required list="disease-options"')+'<datalist id="disease-options">'+[...new Set(data('hp_settings').filter(v=>v.category===(tableName==='hp_ncd_monthly'?'ncd':'cd')).map(v=>v.value['รายการ']))].map(v=>`<option value="${e(v)}">`).join('')+'</datalist>';if(tableName==='hp_ncd_monthly')fields+=`<label>ประเภท<select name="case_type"><option ${r.case_type==='รายเก่า'?'selected':''}>รายเก่า</option><option ${r.case_type==='รายใหม่'?'selected':''}>รายใหม่</option></select></label>`;if(tableName==='hp_budget_monthly')fields+=`<label>ประเภทแผน<select name="kind"><option value="annual_plan" ${r.kind!=='monthly_plan'?'selected':''}>แผนทั้งปี</option><option value="monthly_plan" ${r.kind==='monthly_plan'?'selected':''}>แผนรายเดือน</option></select></label>`;if(['hp_budget_monthly','hp_finance_monthly'].includes(tableName))fields+=`<label>สถานะตรวจสอบ<select name="review_status">${['accepted','pending','rejected'].map(v=>`<option ${r.review_status===v?'selected':''}>${v}</option>`).join('')}</select></label>`;if(tableName==='hp_service_stats')fields+=field('ประเภทบริการ','service_name',r.service_name,'text','required');if(tableName==='hp_staff')fields+=field('วิชาชีพ','profession',r.profession,'text','required')+field('บุคลากรสนับสนุน','support_count',r.support_count);}
 if(tableName==='hp_data_quality')fields=field('รายละเอียด','detail',r.detail,'text','required')+field('ประเภทปัญหา','issue_type',r.issue_type,'text','required')+`<label>ตรวจสอบแล้ว<select name="resolved"><option value="false">ยังไม่ตรวจสอบ</option><option value="true" ${r.resolved?'selected':''}>ตรวจสอบแล้ว</option></select></label>`;
 if(tableName==='hp_settings')fields=field('รหัสตั้งค่า','setting_key',r.setting_key,'text',id?'readonly':'required')+field('หมวด','category',r.category,'text','required')+`<label>ข้อมูล JSON<textarea name="value" required rows="6">${e(JSON.stringify(r.value??{},null,2))}</textarea></label>`;
 openDialog((id?'แก้ไข':'เพิ่ม')+' '+tableLabels[tableName],`<form id="record-form" data-id="${e(id??'')}" data-table="${tableName}"><div class="form-grid">${fields}</div><div id="record-error" class="form-error"></div><div class="form-actions"><button type="submit" class="primary">บันทึกข้อมูล</button></div></form>`);
}
function downloadCsv(name,rows){if(!rows.length){openDialog('ส่งออกข้อมูล','ไม่พบข้อมูลในช่วงที่เลือก');return;}const keys=[...new Set(rows.flatMap(Object.keys))].filter(k=>!['raw_data','access_token'].includes(k));const csv='\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]===null||r[k]===undefined?'':typeof r[k]==='object'?JSON.stringify(r[k]):String(r[k])))].map(row=>row.map(v=>'"'+String(v).replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`kelang-${name}-FY${state.year}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportData(name){const mapping={finance:'hp_finance_monthly',ncd:'hp_ncd_monthly',cd:'hp_cd_monthly',manage:state.manageTable};const tableName=mapping[name];downloadCsv(name,profileRows(tableName));}
async function reloadProfile(){state.profile=await loadProfile();await loadPermissions();render();}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{
 if(b.id==='load-hp-accounts'){state.hpAccounts=(await accountApi({action:'list'})).accounts;render();return;}
 if(b.dataset.resetAccount){if(!admin())throw new Error('เฉพาะ ADMIN เท่านั้น');openDialog('ตั้งรหัสผ่านใหม่เฉพาะบัญชี Hospital Profile','<form id="reset-account-form" data-user-id="'+e(b.dataset.resetAccount)+'"><label>รหัสผ่านใหม่<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><div class="form-error" id="account-reset-error"></div><button type="submit" class="primary">บันทึกรหัสผ่านใหม่</button></form>');return;}
 if(b.id==='stop-kpi-check'){state.stopKpi=true;state.kpiAdminNotice='กำลังหยุดหลังคำขอปัจจุบัน';render();return;}
 if(b.id==='check-all-kpi'){await checkPublication(state.kpis.map(k=>k.kpi_id));return;}
 if(b.dataset.checkKpi){await checkPublication([b.dataset.checkKpi]);return;}
 if(b.dataset.autoKpi){await savePublication(b.dataset.autoKpi,{mode:'auto'});state.kpiAdminNotice='บันทึกโหมดอัตโนมัติแล้ว';render();return;}
 if(b.dataset.kpi){detailKpi(b.dataset.kpi,b.dataset.detailFacility);return;}
 if(b.dataset.profile){location.hash='unit/'+b.dataset.profile+'/resources';return;}
 if(b.dataset.finance){const code=b.dataset.finance;const f=state.facilities.find(f=>f.facility_code===code);openDialog('เบิกจ่ายรายเดือน '+f.short_name,table(['เดือน','ยอดจ่าย (บาท)'],fiscalMonths.map((m,i)=>[monthNames[i],fmt(sum(profileRows('hp_finance_monthly').filter(r=>r.facility_code===code&&+r.period.slice(5,7)===m&&r.review_status==='accepted').map(r=>r.amount)),2)])));return;}
 if(b.dataset.editProfile){profileForm(b.dataset.editProfile);return;}
 if(b.dataset.editRecord){recordForm(b.dataset.editRecord);return;}
 if(b.dataset.deleteRecord){if(!confirm('ลบรายการนี้หรือไม่? ระบบเก็บประวัติไว้ใน Audit Log'))return;const key=state.manageTable==='hp_settings'?'setting_key':'id';await rest(state.manageTable,`${key}=eq.${encodeURIComponent(b.dataset.deleteRecord)}`,'DELETE');await reloadProfile();return;}
 if(b.dataset.revokeUser){if(!confirm('ถอนสิทธิ์ของบัญชีนี้สำหรับหน่วยบริการที่เลือกหรือไม่?'))return;await rest('hp_user_facilities',`user_id=eq.${b.dataset.revokeUser}&facility_code=eq.${b.dataset.revokeCode}`,'DELETE');await loadPermissions();render();return;}
 if(b.dataset.liveHdc){const k=state.kpis.find(k=>k.kpi_id===b.dataset.liveHdc);const generation=state.generation;const year=state.year;state.loading=true;render();try{const result=await fetchHdc(k,year,state.facilities,true,true);if(generation!==state.generation||year!==state.year)return;state.hdc[k.kpi_id]=result;state.hdcNotice=result.error?'HDC API สดไม่สำเร็จ: '+result.error+(result.rows.length?' • แสดงข้อมูลจริงล่าสุดที่มี':' • ยังไม่มีข้อมูลที่ใช้แสดงได้'):'HDC API สดสำเร็จ: '+k.name+' ปี '+year+' • '+result.rows.length+' แถวของหน่วยบริการที่เลือก';}finally{if(generation===state.generation){state.loading=false;render();}}return;}
 if(b.dataset.exportHdc){const k=state.kpis.find(k=>k.kpi_id===b.dataset.exportHdc);downloadCsv(k.table,recordSet(k).map(r=>({facility_code:r.facility.facility_code,facility_name:r.facility.facility_name,fiscal_year:state.year,period:state.period,scope:k.scope,kpi:k.name,numerator:r.eligible?r.numerator:'N/A',denominator:r.eligible?r.denominator:'N/A',value:r.eligible?r.value:'N/A',source_date:r.source_date})));return;}
 if(b.dataset.export){exportData(b.dataset.export);return;}
 if(b.id==='add-record'){recordForm();return;}
 if(b.id==='audit-view'){const logs=await rest('hp_audit_logs','select=*&order=created_at.desc&limit=100');openDialog('ประวัติการเปลี่ยนแปลงล่าสุด',table(['เวลา','ตาราง','หน่วย','คำสั่ง','ผู้ใช้'],logs.map(r=>[e(formatSourceDate(r.created_at)),e(r.table_name),e(r.facility_code),e(r.operation),e(r.user_id??'migration')])));return;}
 if(b.id==='manage-login'){openLogin();return;}
}catch(error){openDialog('ดำเนินการไม่สำเร็จ',`<p class="danger-text">${e(error.message)}</p>`);}});
document.addEventListener('click',event=>{const mode=event.target.closest('[data-rate-mode]');if(mode){state.rateMode=mode.dataset.rateMode==='rate';render();document.querySelector('[data-rate-mode="'+mode.dataset.rateMode+'"]')?.focus({preventScroll:true});return;}const button=event.target.closest('[data-ncd-unit]');if(button){state.facility=button.dataset.ncdUnit;updateFilters();render();}});
document.addEventListener('change',async event=>{const target=event.target;if(target.dataset.publishKpi){target.disabled=true;try{await savePublication(target.dataset.publishKpi,{mode:target.checked?'show':'hide'});state.kpiAdminNotice='บันทึกการแสดงผลแล้ว มีผลกับหน้าเว็บของทุกคน';}catch(error){state.kpiAdminNotice='บันทึกไม่สำเร็จ: '+error.message;}render();return;}if(target.id==='kpi-selector'){state.kpi=target.value;render();}if(target.dataset.compare){if(target.checked)state.selected.add(target.dataset.compare);else state.selected.delete(target.dataset.compare);render();}if(target.id==='manage-table'){state.manageTable=target.value;state.search='';render();}if(target.id==='manage-search'){state.search=target.value;render();}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['login-form','profile-form','record-form','permissions-form','create-account-form','reset-account-form'].includes(form.id))return;event.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;const values=Object.fromEntries(new FormData(form));const errorId={ 'create-account-form':'account-error','reset-account-form':'account-reset-error','login-form':'login-error','profile-form':'profile-error','record-form':'record-error','permissions-form':'permissions-error'}[form.id];try{
 if(form.id==='create-account-form'){const facilities=[...form.querySelectorAll('input[name=account_facility]:checked')].map(el=>el.value);const button=form.querySelector('button[type=submit]');button.disabled=true;try{const response=await accountApi({action:'create',name:values.name,email:values.email,password:values.password,role:values.role,facilities});form.reset();state.accountNotice=response.message;state.hpAccounts=(await accountApi({action:'list'})).accounts;await loadPermissions();render();}catch(error){$('account-error').textContent=error.message;}finally{button.disabled=false;}return;}
 if(form.id==='reset-account-form'){await accountApi({action:'reset_password',user_id:form.dataset.userId,password:values.password});form.reset();$('dialog').close();state.accountNotice='ตั้งรหัสผ่านใหม่สำเร็จ';render();return;}
 if(form.id==='login-form'){await login(values.email,values.password);await reloadProfile();$('dialog').close();state.route='manage';location.hash='manage';render();}
 if(form.id==='profile-form'){const numeric=['population','male','female','households','communities','staff_count','support_count','volunteer_count'];numeric.forEach(k=>values[k]=number(values[k]));if(values.population!==null&&values.male!==null&&values.female!==null&&values.population!==values.male+values.female)throw new Error('ประชากรรวมต้องเท่ากับชาย + หญิง');await refreshSession();await request(`${runtime.supabaseUrl}/rest/v1/rpc/hp_save_profile`,{method:'POST',headers:{apikey:runtime.supabaseKey,Authorization:`Bearer ${currentSession().access_token}`,'Content-Type':'application/json'},body:JSON.stringify({code:form.dataset.code,year:state.year,fields:values})});$('dialog').close();await reloadProfile();}
 if(form.id==='record-form'){const tableName=form.dataset.table;['fiscal_year','amount','case_count','visit_count','staff_count','support_count'].forEach(k=>{if(k in values)values[k]=number(values[k]);});if('period' in values)values.period=values.period?values.period+'-01':null;if(tableName==='hp_budget_monthly'&&values.kind==='annual_plan')values.period=null;if(values.period&&fiscalYear(+values.period.slice(0,4),+values.period.slice(5,7))!==values.fiscal_year)throw new Error('เดือนที่เลือกไม่อยู่ในปีงบประมาณนี้');if('resolved' in values)values.resolved=values.resolved==='true';if('value' in values)values.value=JSON.parse(values.value);if(tableName==='hp_data_quality'&&!form.dataset.id)values.source_key='manual-'+crypto.randomUUID();const id=form.dataset.id;const query=id?(tableName==='hp_settings'?'setting_key':'id')+'=eq.'+encodeURIComponent(id):'';await rest(tableName,query,id?'PATCH':'POST',values);$('dialog').close();await reloadProfile();}
 if(form.id==='permissions-form'){const existing=state.permissions.find(p=>p.user_id===values.user_id&&p.facility_code===values.facility_code);await rest('hp_user_facilities',existing?`user_id=eq.${values.user_id}&facility_code=eq.${values.facility_code}`:'',existing?'PATCH':'POST',values);await loadPermissions();render();}
}catch(error){$(errorId).textContent=error.message;}finally{button.disabled=false;}});
$('dialog-close').addEventListener('click',()=>$('dialog').close());$('dialog').addEventListener('click',event=>{if(event.target===$('dialog')){const rect=$('dialog').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('dialog').close();}});
$('auth-button').addEventListener('click',async()=>{if(currentSession()){try{await logout();state.permissions=[];state.personnelLinks=[];state.profile.tables.hp_personnel=[];render();await reloadProfile();}catch(error){openDialog('ออกจากระบบ',e(error.message));}}else openLogin();});
$('refresh').addEventListener('click',()=>load(true));
for(const key of ['year','period','scope','facility','category'])$(key).addEventListener('change',()=>{state[key]=key==='year'?+$(key).value:$(key).value;if(key==='facility'&&state.route==='units'){location.hash=state.facility==='all'?'units':'unit/'+state.facility+'/'+state.unitTab;return;}if(key==='scope'){state.route=state.scope==='AREA'?'area':state.scope==='SERVICE'?'service':'overview';history.replaceState(null,'','#'+state.route);}if(key==='year'){state.hdc={};state.previous={};load();}else render();});
window.addEventListener('hashchange',navigate);
try{
 const [facilitiesMaster,kpiMaster,inventory]=await Promise.all([request(new URL('./config/facilities.json',import.meta.url)),request(new URL('./config/kpi-master.json',import.meta.url)),request(new URL('./config/report-inventory.json',import.meta.url))]);state.facilities=facilitiesMaster;state.kpis=kpiMaster;state.inventory=inventory;state.selected=new Set(facilitiesMaster.map(f=>f.facility_code));$('navigation').innerHTML=routes.filter(r=>r[0]!=='profile').map(([id,icon,label])=>`<a href="#${id}"><span class="nav-icon" aria-hidden="true">${icon}</span>${e(label)}</a>`).join('');fiscalMonths.forEach((m,i)=>$('period').add(new Option(monthNames[i],String(m))));[...new Set(kpiMaster.map(k=>k.category))].forEach(c=>$('category').add(new Option(c,c)));navigate();await load();
}catch(error){$('view').innerHTML=`<div class="notice error">ไม่สามารถเริ่มระบบ: ${e(error.message)}</div>`;}
